// Canonical, dependency-free financial arithmetic. Browser copy is generated by
// scripts/sync-financial.mjs and checked byte-for-byte in regression tests.
// Monetary boundaries round half away from zero; item unit discounts retain the
// established ceiling-to-cent policy. All intermediate arithmetic is integer.
const MAX_CENTS = BigInt(Number.MAX_SAFE_INTEGER);
export const MAX_STORED_CENTS = 999999999999; // PostgreSQL Decimal(12,2)
export const financialError = (message: string) => Object.assign(new Error(message), { status: 400 });
export function assertNoTax(value: unknown) {
  if (value === undefined || value === null) return;
  const amount = typeof value === 'string' && value.trim() !== '' ? Number(value) : value;
  if (typeof amount !== 'number' || !Number.isFinite(amount) || amount !== 0) {
    throw financialError('Tax is not supported');
  }
}
export function assertNoTaxPayload(payload: unknown) {
  if (payload && typeof payload === 'object' && Object.hasOwn(payload, 'tax')) {
    assertNoTax((payload as { tax?: unknown }).tax);
  }
}
function rational(value: unknown): [bigint, bigint] {
  const text = String(value ?? 0).trim();
  const match = /^([+-]?)(\d+)(?:\.(\d*))?(?:e([+-]?\d+))?$/i.exec(text);
  if (!match) throw financialError('Invalid finite monetary value');
  const exponent = Number(match[4] || 0) - (match[3]?.length || 0);
  if (Math.abs(exponent) > 30) throw financialError('Monetary precision out of range');
  let n = BigInt(match[2] + (match[3] || '')) * (match[1] === '-' ? -1n : 1n);
  if (exponent >= 0) return [n * 10n ** BigInt(exponent), 1n];
  return [n, 10n ** BigInt(-exponent)];
}
function divide(n: bigint, d: bigint, ceiling = false): bigint {
  if (d <= 0n) throw financialError('Invalid divisor');
  if (ceiling) return n / d + (n > 0n && n % d !== 0n ? 1n : 0n);
  const sign = n < 0n ? -1n : 1n;
  return sign * ((n * sign + d / 2n) / d);
}
export function toCents(value: unknown): number {
  const [n, d] = rational(value); const cents = divide(n * 100n, d);
  if (cents > MAX_CENTS || cents < -MAX_CENTS) throw financialError('Monetary amount out of range');
  return Number(cents);
}
export const fromCents = (cents: number) => {
  if (!Number.isSafeInteger(cents) || Math.abs(cents) > Number(MAX_CENTS)) throw financialError('Invalid minor units');
  return cents / 100;
};
export const addMoney = (...values: unknown[]) => fromCents(values.reduce<number>((sum, value) => sum + toCents(value), 0));
export function quantity(value: unknown, allowZero = false): number {
  const n = Number(value);
  if (!Number.isSafeInteger(n) || n < 0 || (!allowZero && n === 0)) throw financialError('Quantity must be a positive whole number');
  return n;
}
export function percent(value: unknown): number {
  const n = Number(value ?? 0);
  if (!Number.isFinite(n) || n < 0 || n > 100) throw financialError('Discount must be between 0 and 100%');
  return n;
}
export function discountedUnit(price: unknown, discount: unknown = 0): number {
  const cents = toCents(price); if (cents < 0) throw financialError('Price must be non-negative');
  const [p, d] = rational(percent(discount));
  return fromCents(Number(divide(BigInt(cents) * (100n * d - p), 100n * d, true)));
}
export function lineTotal(qty: unknown, price: unknown, discount: unknown = 0): number {
  return fromCents(quantity(qty, true) * toCents(discountedUnit(price, discount)));
}
export function discountAmount(total: unknown, discount: unknown = 0): number {
  const [p, d] = rational(percent(discount));
  return fromCents(Number(divide(BigInt(toCents(total)) * p, 100n * d)));
}
// Largest remainder allocation: stable input order breaks ties. Exactly conserves
// the original amount, including zero-price/free lines and the final cent.
export function allocateCents(amount: number, weights: number[]): number[] {
  if (!Number.isSafeInteger(amount) || amount < 0 || weights.some(w => !Number.isSafeInteger(w) || w < 0)) throw financialError('Invalid allocation');
  const total = weights.reduce((s, w) => s + BigInt(w), 0n);
  if (total === 0n) { if (amount !== 0) throw financialError('Cannot allocate a nonzero amount to zero weights'); return weights.map(() => 0); }
  const rows = weights.map((w, index) => ({ index, value: Number(BigInt(amount) * BigInt(w) / total), remainder: BigInt(amount) * BigInt(w) % total }));
  let left = amount - rows.reduce((s, r) => s + r.value, 0);
  for (const row of [...rows].sort((a, b) => a.remainder === b.remainder ? a.index - b.index : a.remainder > b.remainder ? -1 : 1)) { if (left-- <= 0) break; row.value++; }
  return rows.map(r => r.value);
}
export function cumulativeValue(total: unknown, returned: unknown, sold: unknown): number {
  const count = quantity(sold); const used = quantity(returned, true);
  if (used > count) throw financialError('Returned quantity exceeds original quantity');
  return fromCents(Number(divide(BigInt(toCents(total)) * BigInt(used), BigInt(count))));
}
export function saleTotals(items: any[], orderDiscount: unknown = 0, tax: unknown = 0) {
  assertNoTax(tax);
  const totals = items.map(i => lineTotal(i.totalBaseUnits ?? i.quantity, i.sellingPrice, i.discount ?? 0));
  const subtotal = addMoney(...totals); const discount = discountAmount(subtotal, orderDiscount);
  const allocations = allocateCents(toCents(discount), totals.map(toCents));
  if ([subtotal, addMoney(subtotal, -discount)].some(value => toCents(value) > MAX_STORED_CENTS)) throw financialError('Invoice amount exceeds database monetary range');
  return { subtotal, discount, net: addMoney(subtotal, -discount), lines: totals.map((total, i) => ({ total, orderDiscount: fromCents(allocations[i]), allocatedTax: 0, eligibleNet: addMoney(total, -fromCents(allocations[i])) })) };
}
export function invoiceLines(invoice: any) {
  const items: any[] = invoice.items || [];
  const totals = items.map(i => i.totalPrice != null ? toCents(i.totalPrice) : toCents(lineTotal(i.quantity, i.sellingPrice, i.discount ?? 0)));
  const allocations = allocateCents(toCents(discountAmount(fromCents(totals.reduce((s, n) => s + n, 0)), invoice.discount ?? 0)), totals);
  const taxAllocations = allocateCents(toCents(invoice.tax ?? 0), totals.map((t, i) => t - allocations[i]));
  const returns: any[] = Array.isArray(invoice.returns) ? invoice.returns : [];
  const hasReturnDetails = returns.length > 0 && returns.every(r => Array.isArray(r.items) && r.items.length > 0);
  const returnedTaxByItem = new Map<number, number>();
  if (hasReturnDetails) {
    for (const itemReturn of returns.flatMap(r => r.items)) {
      const itemId = Number(itemReturn.invoiceItemId);
      returnedTaxByItem.set(itemId, addMoney(returnedTaxByItem.get(itemId) ?? 0, itemReturn.taxAmount ?? 0));
    }
  }
  return items.map((item, index) => {
    const eligible = item.eligibleNetAmount != null ? Number(item.eligibleNetAmount) : fromCents(totals[index] - allocations[index]);
    const returned = cumulativeValue(eligible, item.returnedQty || 0, item.quantity);
    const tax = item.allocatedTax != null ? Number(item.allocatedTax) : fromCents(taxAllocations[index]);
    const returnedTax = hasReturnDetails
      ? returnedTaxByItem.get(Number(item.id)) ?? 0
      : cumulativeValue(tax, item.returnedQty || 0, item.quantity);
    return { ...item, originalLineTotal: fromCents(totals[index]), allocatedOrderDiscount: item.allocatedOrderDiscount != null ? Number(item.allocatedOrderDiscount) : fromCents(allocations[index]), eligibleNetAmount: eligible,
      allocatedTax: tax, returnedTax, remainingTax: addMoney(tax, -returnedTax),
      returnedNetAmount: returned, remainingNetAmount: addMoney(eligible, -returned), remainingQuantity: quantity(item.quantity) - quantity(item.returnedQty || 0, true) };
  });
}
export function refundByMethod(payments: any[], refund: unknown) {
  const methods = ['cash', 'card', 'transfer'];
  const buckets = methods.map(method => toCents(addMoney(...payments.filter(p => p.method === method).map(p => p.amount))));
  if (buckets.some(n => n < 0) || payments.some(p => !methods.includes(p.method) && toCents(p.amount) !== 0)) throw financialError('Historical refund payment methods require reconciliation');
  const cents = toCents(refund);
  if (cents > buckets.reduce((s, n) => s + n, 0)) throw financialError('Refund exceeds available payments');
  return allocateCents(cents, buckets).map((amount, i) => ({ method: methods[i], amount: fromCents(amount) })).filter(p => p.amount > 0);
}
export function refundSplit(net: unknown, paid: unknown, eligible: unknown) {
  const n = toCents(net), p = toCents(paid), r = toCents(eligible);
  if (n < 0 || p < 0 || p > n || r < 0 || r > n) throw financialError('Financial reconciliation required before return');
  const money = Math.min(p, r);
  return { refundedAmount: fromCents(money), debtReduction: fromCents(r - money), netAmount: fromCents(n - r), paidAmount: fromCents(p - money), debtAmount: fromCents(n - r - p + money) };
}
